#include "dual_state_cuda_resident.cuh"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=2;c.d=16;c.s=8;c.m=16;c.e=32;c.vocab=261;CpuModel cpu(c);std::mt19937 rng(819);std::normal_distribution<float>d(0,.1f);for(auto&kv:cpu.w)for(auto&z:kv.second)z=kv.first.find("norm")!=std::string::npos?1.f:d(rng);CudaResident gpu(cpu);auto state=cpu.initial();double worst=0;size_t checks=0;auto compare=[&](const Vec&a,const Vec&b){for(size_t j=0;j<a.size();++j){double e=std::abs(a[j]-b[j]);if(!std::isfinite(e)||e>2e-5*(1+std::abs(a[j])))throw std::runtime_error("parity");worst=std::max(worst,e);++checks;}};for(int i=0;i<32;++i){if(i==16){gpu.reset();state=cpu.initial();}unsigned t=rng()%c.vocab;compare(cpu.step(t,state),gpu.step(t));for(unsigned l=0;l<c.layers;++l){compare(state[l].s,gpu.s[l]->host());compare(state[l].m,gpu.m[l]->host());}}printf("PASS resident forward checks=%zu max_abs=%.9g reset included\n",checks,worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
